import sys

def count_primes(n):
    if n <= 2:
        return 0
    if n == 3:
        return 1
    # Odd-only sieve using bytearray
    # Index i represents 2*i + 3
    # Limit is n - 1. Max index for m = n - 1 is (n - 4) // 2
    size = (n - 3) // 2 + 1
    sieve = bytearray([1]) * size
    limit = int((n - 1) ** 0.5)
    max_i = (limit - 3) // 2
    for i in range(max_i + 1):
        if sieve[i]:
            p = 2 * i + 3
            start = (p * p - 3) // 2
            sieve[start::p] = bytearray((size - start - 1) // p + 1)
    return 1 + sieve.count(1)

if __name__ == '__main__':
    print(count_primes(int(sys.argv[1])))

import sys

def count_primes(n):
    if n <= 2:
        return 0
    size = (n - 2) // 2
    sieve = bytearray([1]) * size
    limit = int((n - 1) ** 0.5)
    max_i = (limit - 3) // 2
    for i in range(max_i + 1):
        if sieve[i]:
            p = 2 * i + 3
            start = (p * p - 3) // 2
            sieve[start::p] = bytearray((size - start - 1) // p + 1)
    return 1 + sieve.count(1)

if __name__ == '__main__':
